insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000048301', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000225', 'multiple_choice', 'easy', 'published', 'Em um esboço tridimensional preparado para uma aula, O ponto $P=(1,1,3)$ pertence ao plano $x+2y-z=0$. Qual dos pontos abaixo também pertence a ele?') on conflict (id) do update set subject_id = excluded.subject_id, source_id = excluded.source_id, kind = excluded.kind, difficulty = excluded.difficulty, publication_status = excluded.publication_status, statement_markdown = excluded.statement_markdown;
