insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000483011', '40000000-0000-4000-8000-000000048301', 'Faça primeiro um pequeno registro das grandezas conhecidas e daquilo que a pergunta realmente pede.', 1), ('60000000-0000-4000-8000-000000483012', '40000000-0000-4000-8000-000000048301', 'Substitua as coordenadas de cada candidato na equação do plano.', 2), ('60000000-0000-4000-8000-000000483013', '40000000-0000-4000-8000-000000048301', 'O ponto pertence quando os dois lados da igualdade coincidem.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048301', '$(2,1,4)$.', 'Trate as coordenadas como informações de posição: alinhar cada eixo antes de operar evita conclusões visuais enganosas. Um plano é identificado por um ponto e um vetor normal. Na equação cartesiana, os coeficientes de x, y e z formam esse normal; substituir um ponto ou comparar normais é uma forma direta de conferir pertencimento, paralelismo e perpendicularidade. A alternativa A coincide com a relação obtida; a alternativa B ($(1,2,2)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000483011', '40000000-0000-4000-8000-000000048301', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000483012', '40000000-0000-4000-8000-000000048301', 'Calcule o lado esquerdo', '$2+2-(4)=0.$', 2), ('70000000-0000-4000-8000-000000483013', '40000000-0000-4000-8000-000000048301', 'Compare', '$0=0.$', 3), ('70000000-0000-4000-8000-000000483014', '40000000-0000-4000-8000-000000048301', 'Conclua', 'Esse ponto satisfaz a equação do plano.', 4), ('70000000-0000-4000-8000-000000483015', '40000000-0000-4000-8000-000000048301', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
