insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000483071', '40000000-0000-4000-8000-000000048307', 'Escreva a relação matemática antes de substituir os valores; isso torna sinais e denominadores mais visíveis.', 1), ('60000000-0000-4000-8000-000000483072', '40000000-0000-4000-8000-000000048307', 'Substitua as coordenadas de cada candidato na equação do plano.', 2), ('60000000-0000-4000-8000-000000483073', '40000000-0000-4000-8000-000000048307', 'O ponto pertence quando os dois lados da igualdade coincidem.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048307', '$(8,1,10)$.', 'Uma boa conferência separa a ideia geométrica da conta numérica e testa o resultado na relação inicial. Um plano é identificado por um ponto e um vetor normal. Na equação cartesiana, os coeficientes de x, y e z formam esse normal; substituir um ponto ou comparar normais é uma forma direta de conferir pertencimento, paralelismo e perpendicularidade. A alternativa A coincide com a relação obtida; a alternativa B ($(7,2,8)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
