insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000483091', '40000000-0000-4000-8000-000000048309', 'Não tente calcular tudo de uma vez: destaque primeiro a propriedade que caracteriza o problema.', 1), ('60000000-0000-4000-8000-000000483092', '40000000-0000-4000-8000-000000048309', 'Substitua as coordenadas de cada candidato na equação do plano.', 2), ('60000000-0000-4000-8000-000000483093', '40000000-0000-4000-8000-000000048309', 'O ponto pertence quando os dois lados da igualdade coincidem.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048309', '$(10,1,12)$.', 'A notação compacta não substitui o raciocínio: identificar o tipo de objeto é o passo que determina qual fórmula usar. Um plano é identificado por um ponto e um vetor normal. Na equação cartesiana, os coeficientes de x, y e z formam esse normal; substituir um ponto ou comparar normais é uma forma direta de conferir pertencimento, paralelismo e perpendicularidade. A alternativa A coincide com a relação obtida; a alternativa B ($(9,2,10)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
