insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000483171', '40000000-0000-4000-8000-000000048317', 'Escreva a relação matemática antes de substituir os valores; isso torna sinais e denominadores mais visíveis.', 1), ('60000000-0000-4000-8000-000000483172', '40000000-0000-4000-8000-000000048317', 'Os coeficientes de x, y e z formam um vetor normal.', 2), ('60000000-0000-4000-8000-000000483173', '40000000-0000-4000-8000-000000048317', 'Mantenha o sinal do coeficiente de y.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048317', '$n=(9,-10,2)$.', 'Uma boa conferência separa a ideia geométrica da conta numérica e testa o resultado na relação inicial. Um plano é identificado por um ponto e um vetor normal. Na equação cartesiana, os coeficientes de x, y e z formam esse normal; substituir um ponto ou comparar normais é uma forma direta de conferir pertencimento, paralelismo e perpendicularidade. A alternativa A coincide com a relação obtida; a alternativa B ($(2,9,-10)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000483171', '40000000-0000-4000-8000-000000048317', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000483172', '40000000-0000-4000-8000-000000048317', 'Leia os coeficientes', 'A equação está na forma ax mais by mais cz igual a d.', 2), ('70000000-0000-4000-8000-000000483173', '40000000-0000-4000-8000-000000048317', 'Forme o normal', '$n=(9,-10,2).$', 3), ('70000000-0000-4000-8000-000000483174', '40000000-0000-4000-8000-000000048317', 'Verifique', 'Esse vetor é perpendicular a qualquer direção contida no plano.', 4), ('70000000-0000-4000-8000-000000483175', '40000000-0000-4000-8000-000000048317', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000048318', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000225', 'multiple_choice', 'medium', 'published', 'Durante uma correção de prova, considere a seguinte situação: A reta $r(t)=(0,1,0)+t(1,1,1)$ encontra o plano $x+y+z=7$. Qual é o parâmetro t?') on conflict (id) do update set subject_id = excluded.subject_id, source_id = excluded.source_id, kind = excluded.kind, difficulty = excluded.difficulty, publication_status = excluded.publication_status, statement_markdown = excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000483181', '40000000-0000-4000-8000-000000048318', 'A', '$t=2$', 1), ('50000000-0000-4000-8000-000000483182', '40000000-0000-4000-8000-000000048318', 'B', '$t=1$', 2), ('50000000-0000-4000-8000-000000483183', '40000000-0000-4000-8000-000000048318', 'C', '$t=3$', 3), ('50000000-0000-4000-8000-000000483184', '40000000-0000-4000-8000-000000048318', 'D', '$t=0$', 4) on conflict (id) do update set question_id = excluded.question_id, label = excluded.label, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
