insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000483191', '40000000-0000-4000-8000-000000048319', 'Não tente calcular tudo de uma vez: destaque primeiro a propriedade que caracteriza o problema.', 1), ('60000000-0000-4000-8000-000000483192', '40000000-0000-4000-8000-000000048319', 'Substitua as coordenadas paramétricas da reta no plano.', 2), ('60000000-0000-4000-8000-000000483193', '40000000-0000-4000-8000-000000048319', 'A soma das três coordenadas será n mais 3t.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048319', '$t=3$.', 'A notação compacta não substitui o raciocínio: identificar o tipo de objeto é o passo que determina qual fórmula usar. Um plano é identificado por um ponto e um vetor normal. Na equação cartesiana, os coeficientes de x, y e z formam esse normal; substituir um ponto ou comparar normais é uma forma direta de conferir pertencimento, paralelismo e perpendicularidade. A alternativa A coincide com a relação obtida; a alternativa B ($t=2$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000483191', '40000000-0000-4000-8000-000000048319', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000483192', '40000000-0000-4000-8000-000000048319', 'Escreva as coordenadas', '$x=t, y=2+t, z=t.$', 2), ('70000000-0000-4000-8000-000000483193', '40000000-0000-4000-8000-000000048319', 'Substitua no plano', '$t+(2+t)+t=11.$', 3), ('70000000-0000-4000-8000-000000483194', '40000000-0000-4000-8000-000000048319', 'Resolva', '$3t=9 \Rightarrow t=3.$', 4), ('70000000-0000-4000-8000-000000483195', '40000000-0000-4000-8000-000000048319', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
