insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048320', '$t=4$.', 'A resolução fica mais segura quando cada transformação é justificada e o resultado é verificado no enunciado original. Um plano é identificado por um ponto e um vetor normal. Na equação cartesiana, os coeficientes de x, y e z formam esse normal; substituir um ponto ou comparar normais é uma forma direta de conferir pertencimento, paralelismo e perpendicularidade. A alternativa A coincide com a relação obtida; a alternativa B ($t=3$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000483201', '40000000-0000-4000-8000-000000048320', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000483202', '40000000-0000-4000-8000-000000048320', 'Escreva as coordenadas', '$x=t, y=3+t, z=t.$', 2), ('70000000-0000-4000-8000-000000483203', '40000000-0000-4000-8000-000000048320', 'Substitua no plano', '$t+(3+t)+t=15.$', 3), ('70000000-0000-4000-8000-000000483204', '40000000-0000-4000-8000-000000048320', 'Resolva', '$3t=12 \Rightarrow t=4.$', 4), ('70000000-0000-4000-8000-000000483205', '40000000-0000-4000-8000-000000048320', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
