insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048322', '$t=7$.', 'Uma boa conferência separa a ideia geométrica da conta numérica e testa o resultado na relação inicial. Um plano é identificado por um ponto e um vetor normal. Na equação cartesiana, os coeficientes de x, y e z formam esse normal; substituir um ponto ou comparar normais é uma forma direta de conferir pertencimento, paralelismo e perpendicularidade. A alternativa A coincide com a relação obtida; a alternativa B ($t=6$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000483221', '40000000-0000-4000-8000-000000048322', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000483222', '40000000-0000-4000-8000-000000048322', 'Escreva as coordenadas', '$x=t, y=6+t, z=t.$', 2), ('70000000-0000-4000-8000-000000483223', '40000000-0000-4000-8000-000000048322', 'Substitua no plano', '$t+(6+t)+t=27.$', 3), ('70000000-0000-4000-8000-000000483224', '40000000-0000-4000-8000-000000048322', 'Resolva', '$3t=21 \Rightarrow t=7.$', 4), ('70000000-0000-4000-8000-000000483225', '40000000-0000-4000-8000-000000048322', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000048323', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000225', 'multiple_choice', 'medium', 'published', 'Durante uma correção de prova, considere a seguinte situação: A reta $r(t)=(0,7,0)+t(1,1,1)$ encontra o plano $x+y+z=31$. Qual é o parâmetro t?') on conflict (id) do update set subject_id = excluded.subject_id, source_id = excluded.source_id, kind = excluded.kind, difficulty = excluded.difficulty, publication_status = excluded.publication_status, statement_markdown = excluded.statement_markdown;
