insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000483231', '40000000-0000-4000-8000-000000048323', 'Ao final, pergunte se o sinal, a direção ou a dimensão do resultado fazem sentido para a situação.', 1), ('60000000-0000-4000-8000-000000483232', '40000000-0000-4000-8000-000000048323', 'Substitua as coordenadas paramétricas da reta no plano.', 2), ('60000000-0000-4000-8000-000000483233', '40000000-0000-4000-8000-000000048323', 'A soma das três coordenadas será n mais 3t.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048323', '$t=8$.', 'O resultado deve respeitar tanto a definição algébrica quanto a interpretação geométrica do objeto em três dimensões. Um plano é identificado por um ponto e um vetor normal. Na equação cartesiana, os coeficientes de x, y e z formam esse normal; substituir um ponto ou comparar normais é uma forma direta de conferir pertencimento, paralelismo e perpendicularidade. A alternativa A coincide com a relação obtida; a alternativa B ($t=7$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000483231', '40000000-0000-4000-8000-000000048323', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000483232', '40000000-0000-4000-8000-000000048323', 'Escreva as coordenadas', '$x=t, y=7+t, z=t.$', 2), ('70000000-0000-4000-8000-000000483233', '40000000-0000-4000-8000-000000048323', 'Substitua no plano', '$t+(7+t)+t=31.$', 3), ('70000000-0000-4000-8000-000000483234', '40000000-0000-4000-8000-000000048323', 'Resolva', '$3t=24 \Rightarrow t=8.$', 4), ('70000000-0000-4000-8000-000000483235', '40000000-0000-4000-8000-000000048323', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
