insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000483261', '40000000-0000-4000-8000-000000048326', 'Faça primeiro um pequeno registro das grandezas conhecidas e daquilo que a pergunta realmente pede.', 1), ('60000000-0000-4000-8000-000000483262', '40000000-0000-4000-8000-000000048326', 'Planos paralelos têm vetores normais proporcionais.', 2), ('60000000-0000-4000-8000-000000483263', '40000000-0000-4000-8000-000000048326', 'Mudar apenas o termo independente desloca o plano sem girá-lo.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048326', '$1x+2y-z=6$.', 'Trate as coordenadas como informações de posição: alinhar cada eixo antes de operar evita conclusões visuais enganosas. Um plano é identificado por um ponto e um vetor normal. Na equação cartesiana, os coeficientes de x, y e z formam esse normal; substituir um ponto ou comparar normais é uma forma direta de conferir pertencimento, paralelismo e perpendicularidade. A alternativa A coincide com a relação obtida; a alternativa B ($2x+1y-z=4$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
