insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000483281', '40000000-0000-4000-8000-000000048328', 'Ao final, pergunte se o sinal, a direção ou a dimensão do resultado fazem sentido para a situação.', 1), ('60000000-0000-4000-8000-000000483282', '40000000-0000-4000-8000-000000048328', 'Planos paralelos têm vetores normais proporcionais.', 2), ('60000000-0000-4000-8000-000000483283', '40000000-0000-4000-8000-000000048328', 'Mudar apenas o termo independente desloca o plano sem girá-lo.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048328', '$3x+2y-z=8$.', 'O resultado deve respeitar tanto a definição algébrica quanto a interpretação geométrica do objeto em três dimensões. Um plano é identificado por um ponto e um vetor normal. Na equação cartesiana, os coeficientes de x, y e z formam esse normal; substituir um ponto ou comparar normais é uma forma direta de conferir pertencimento, paralelismo e perpendicularidade. A alternativa A coincide com a relação obtida; a alternativa B ($2x+3y-z=4$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
