insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000483331', '40000000-0000-4000-8000-000000048333', 'Ao final, pergunte se o sinal, a direção ou a dimensão do resultado fazem sentido para a situação.', 1), ('60000000-0000-4000-8000-000000483332', '40000000-0000-4000-8000-000000048333', 'Retas paralelas têm vetores diretores proporcionais.', 2), ('60000000-0000-4000-8000-000000483333', '40000000-0000-4000-8000-000000048333', 'Multiplique todas as três coordenadas do vetor pelo mesmo número.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048333', '$(2,2,-2)$.', 'O resultado deve respeitar tanto a definição algébrica quanto a interpretação geométrica do objeto em três dimensões. Relações espaciais são determinadas pelas direções: vetores diretores descrevem retas e vetores normais descrevem planos. Comparar proporcionalidade e produto escalar permite decidir paralelismo e perpendicularidade sem depender de um desenho em perspectiva. A alternativa A coincide com a relação obtida; a alternativa B ($(2,1,-2)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000483331', '40000000-0000-4000-8000-000000048333', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000483332', '40000000-0000-4000-8000-000000048333', 'Leia a direção', '$d=(1,1,-1).$', 2), ('70000000-0000-4000-8000-000000483333', '40000000-0000-4000-8000-000000048333', 'Use um mesmo fator', '$2d=(2,2,-2).$', 3), ('70000000-0000-4000-8000-000000483334', '40000000-0000-4000-8000-000000048333', 'Conclua', 'Como todos os componentes foram multiplicados por 2, a direção é a mesma.', 4), ('70000000-0000-4000-8000-000000483335', '40000000-0000-4000-8000-000000048333', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
