insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000483381', '40000000-0000-4000-8000-000000048338', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000483382', '40000000-0000-4000-8000-000000048338', 'Leia a direção', '$d=(9,1,-1).$', 2), ('70000000-0000-4000-8000-000000483383', '40000000-0000-4000-8000-000000048338', 'Use um mesmo fator', '$2d=(18,2,-2).$', 3), ('70000000-0000-4000-8000-000000483384', '40000000-0000-4000-8000-000000048338', 'Conclua', 'Como todos os componentes foram multiplicados por 2, a direção é a mesma.', 4), ('70000000-0000-4000-8000-000000483385', '40000000-0000-4000-8000-000000048338', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000048339', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000225', 'multiple_choice', 'medium', 'published', 'No painel de um aplicativo de geometria espacial aparece o problema: A reta r tem vetor diretor $d=(1,1,-1)$ e o plano pi tem equação $1x+y-z=4$. Qual relação é garantida?') on conflict (id) do update set subject_id = excluded.subject_id, source_id = excluded.source_id, kind = excluded.kind, difficulty = excluded.difficulty, publication_status = excluded.publication_status, statement_markdown = excluded.statement_markdown;
