insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000483391', '40000000-0000-4000-8000-000000048339', 'Não tente calcular tudo de uma vez: destaque primeiro a propriedade que caracteriza o problema.', 1), ('60000000-0000-4000-8000-000000483392', '40000000-0000-4000-8000-000000048339', 'Os coeficientes do plano formam seu vetor normal.', 2), ('60000000-0000-4000-8000-000000483393', '40000000-0000-4000-8000-000000048339', 'Uma reta é perpendicular a um plano quando seu diretor é paralelo ao normal.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048339', 'A reta é perpendicular ao plano.', 'A notação compacta não substitui o raciocínio: identificar o tipo de objeto é o passo que determina qual fórmula usar. Relações espaciais são determinadas pelas direções: vetores diretores descrevem retas e vetores normais descrevem planos. Comparar proporcionalidade e produto escalar permite decidir paralelismo e perpendicularidade sem depender de um desenho em perspectiva. A alternativa A coincide com a relação obtida; a alternativa B (A reta é paralela ao plano.) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000483391', '40000000-0000-4000-8000-000000048339', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000483392', '40000000-0000-4000-8000-000000048339', 'Extraia o normal', '$n_{\pi}=(1,1,-1).$', 2), ('70000000-0000-4000-8000-000000483393', '40000000-0000-4000-8000-000000048339', 'Compare', '$d=n_{\pi}.$', 3), ('70000000-0000-4000-8000-000000483394', '40000000-0000-4000-8000-000000048339', 'Conclua', 'O diretor da reta tem a direção normal ao plano; portanto, a reta o corta perpendicularmente.', 4), ('70000000-0000-4000-8000-000000483395', '40000000-0000-4000-8000-000000048339', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
