insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048344', 'A reta é perpendicular ao plano.', 'A notação compacta não substitui o raciocínio: identificar o tipo de objeto é o passo que determina qual fórmula usar. Relações espaciais são determinadas pelas direções: vetores diretores descrevem retas e vetores normais descrevem planos. Comparar proporcionalidade e produto escalar permite decidir paralelismo e perpendicularidade sem depender de um desenho em perspectiva. A alternativa A coincide com a relação obtida; a alternativa B (A reta é paralela ao plano.) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
